SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'security_definer',p.prosecdef,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'definition',pg_get_functiondef(p.oid)) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'[]'::jsonb) AS evidence FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname NOT IN('pg_catalog','information_schema') AND p.prokind='f' AND NOT(p.oid=ANY(ARRAY['public.create_onboarding_user(text,text,text)'::regprocedure,'public.onboard_tenant(text,text,text,text,uuid,text,text)'::regprocedure])) AND (p.prosrc ~* '(create_onboarding_user|onboard_tenant)' OR EXISTS(SELECT 1 FROM pg_depend dep WHERE dep.classid='pg_proc'::regclass AND dep.objid=p.oid AND dep.refclassid='pg_proc'::regclass AND dep.refobjid=ANY(ARRAY['public.create_onboarding_user(text,text,text)'::regprocedure,'public.onboard_tenant(text,text,text,text,uuid,text,text)'::regprocedure])));
